@font-face {
  font-family: "Rebond Grotesque";
  src: url("data:font/woff2;charset=utf-8;base64,")
      format("woff2"),
    url("data:font/woff;charset=utf-8;base64,")
      format("woff"),
    // url("RebondGrotesque-Bold.ttf") 
    format("truetype");
  font-weight: bold;
  font-style: normal;
  font-display: swap;
}

